import assert from "node:assert/strict";
import type {GeneratedBody} from "../../src/core/generators/definition";
import type {Block} from "../../src/core/types";
import {decAKnowledgeOracle} from "./dec-a-knowledge-review";
const text=(b:Block)=>b.type==="paragraph"||b.type==="code"?b.text:b.type==="table"?[...b.columns,...b.rows.flat()].join("\n"):b.type==="list"?b.items.join("\n"):"";
const tables=(b:Block[])=>b.flatMap(x=>x.type==="table"?[x]:[]);
function unique(b:GeneratedBody,truth:boolean[]){assert.equal(new Set(b.choices.map(c=>JSON.stringify(c))).size,4);assert.deepEqual(truth.flatMap((x,i)=>x?[i]:[]),[b.correctIndex]);}
function scene(b:GeneratedBody,name:string,values:number[]){const block=b.prompt.find(x=>x.type==="diagram");assert(block?.type==="diagram"&&block.scene.kind==="source_figure");assert.equal(block.scene.profile,`dec-a-${name}`);assert.deepEqual(block.scene.values,values);}
const treeValues=[[16,15,19,10,14],[17,14,19,10,16,18],[18,16,19,15,14,20],[20,18,19,10,14,15,16]];
const treeEdges=[[[0,1],[0,2],[1,3],[1,4]],[[0,1],[0,2],[1,3],[1,4],[2,5]],[[0,1],[0,2],[1,3],[1,4],[2,5]],[[0,1],[0,2],[1,3],[1,4],[2,5],[2,6]]];
export function decATreeOracle(v:number,c:number,o:number){const values=[...treeValues[c]];if(v===1){if(c===0){values[1]=14;values[4]=15;}if(c===1)values[4]=18;}if(v===2){if(c===2)values[4]=17;if(c===1)values[4]=18;}if(v===3){if(c===3)values.splice(0,7,18,14,20,10,16,19,21);if(c===1)values[4]=18;}return {values:values.map(n=>n+o),edges:treeEdges[c]};}
export const decAReviewedAutomaton=[[0,1],[0,2],[0,2]]; // next state for inputs0/1
export const decAReviewedOutputs=[[0,0],[0,1],[0,1]];
export const decAReviewedNetworkEdges=[[0,1],[1,2],[1,3],[1,4],[2,5],[3,6],[4,8],[5,7],[6,7],[7,8]];
const predicates:Record<number,RegExp[]>={1:[/ORはビットごとの論理和/,/XORはビットごとの排他的論理和/],2:[/下位桁から順/,/NISHIN\(1\)/,/j div 2はjを2で割った商の整数部分/,/j mod 2はjを2で割った余り/,/初期値，増分，終値/],3:[/Pの真理値は真/,/or YはXとYの論理和、not XはXの否定/],4:[/入力記号、出力記号の集合が\{0，1\}/,/入力記号は左から順に読み込まれる/,/S₁は初期状態を表し/,/遷移の矢印のラベルは、入力／出力を表している/],6:[/A\(i，j\)、B\(i，j\)/,/初期値，増分，終値/],7:[/mod\(x，13\)は、xを13で割った余り/],8:[/f\(n\): if n≦1 then return 1 else return n＋f\(n−1\)/],11:[/冗長ビットがn＋2ビット/],13:[/均等に配分/,/90％を超えた/,/以外の条件は考慮しなくてよい/],14:[/どれか1台/,/故障は互いに独立/],15:[/受信タスクよりも送信タスクの方が転送速度は速/,/次の転送開始までの時間間隔は十分/],17:[/途中で解放しない/,/同一容量で十分/,/初めは全て空き/,/等しい場合はA，B，C/],26:[/伝送効率を50％/],29:[/HTTPで通信/],50:[/5年間/,/割引率は考慮しなくてもよい/],57:[/それぞれ100円、150円/],58:[/3年後/,/耐用年数は4年/,/定額法の償却率は0.250/,/残存価額は0円/],59:[/変動費率、固定費は変わらない/],60:[/労働者派遣法に基づく/,/太線部分/]};
export function decAGeneratorOracle(n:number,b:GeneratedBody,v:number[]){
 const prompt=b.prompt.map(text).join("\n"),choices=b.choices.map(c=>c.map(text).join("\n")),nums=choices.map(s=>Number(s.replaceAll(",","")));
 for(const pattern of predicates[n]??[])assert.match(prompt,pattern,`Q${n} visible premise`);assert(b.explanation.length>50);
 if(n===1){const w=Number(prompt.match(/(\d)ビットの2進正数/)![1]);assert.equal(w,v[0]);const mod=2**w;unique(b,choices.map(c=>{const m=c.match(/\(n (OR|XOR) ([01]+)\)＋([01]+)/)!;assert(m);const mask=parseInt(m[2],2),add=parseInt(m[3],2);return Array.from({length:mod-1},(_,i)=>i+1).every(x=>(((m[1]==="OR"?x|mask:x^mask)+add)%mod)===(mod-x)%mod);}));
 }else if(n===2){const w=Number(prompt.match(/を(\d)桁の2進数/)![1]),upper=Number(prompt.match(/0＜j＜(\d+)/)![1]);assert.equal(w,v[0]);scene(b,"binary-flow",[w]);const programs=b.choices.map(c=>tables(c)[0].rows[0]);unique(b,programs.map(program=>{for(let x=1;x<upper;x++){let j=x;const bits:number[]=[];for(let k=0;k<w;k++)for(const line of program){const value=line.includes("mod")?j%2:Math.floor(j/2);if(line.startsWith("j"))j=value;else bits.push(value);}if(bits.some(x=>x<0||x>1)||bits.map(String).reverse().join("")!==x.toString(2).padStart(w,"0"))return false;}return true;}));
 }else if(n===3){const qneg=prompt.includes("or (not Q)"),rneg=prompt.includes("or (not R)");assert.deepEqual([Number(qneg),Number(rneg)],v);const assignments=[false,true].flatMap(q=>[false,true].map(r=>({q,r,works:(qneg?!q:q)&&(!(qneg?!q:q)||(rneg?!r:r))})));unique(b,b.choices.map(c=>{const [qs,rs]=tables(c)[0].rows[0];return assignments.some(a=>a.works&&a.q===(qs==="真")&&a.r===(rs==="真"));}));
 }else if(n===4){const inputs=["0011001110","0110110010","1100011011","1011100100","1110010110","0011101101"],input=prompt.match(/([01]{10})を入力記号/)![1];assert.equal(input,inputs[v[0]]);scene(b,"automaton",[0]);let s=0,out="";for(const x of input){const bit=Number(x);out+=decAReviewedOutputs[s][bit];s=decAReviewedAutomaton[s][bit];}unique(b,choices.map(c=>c===out));assert(b.explanation.includes(out));
 }else if(n===5){assert.equal(prompt,"2分探索木になっている2分木はどれか。");const valid=b.choices.map((c,i)=>{const f=c[0];assert(f.type==="diagram"&&f.scene.kind==="source_figure");assert.deepEqual(f.scene,{kind:"source_figure",profile:"dec-a-bst",values:[v[0],i,v[1]]});const {values,edges}=decATreeOracle(...f.scene.values as [number,number,number]);const visit=(at:number,lo:number,hi:number):boolean=>values[at]>lo&&values[at]<hi&&edges.filter(e=>e[0]===at).every(([_,child])=>{const left=child===1||child===3||child===5&&i!==2;return visit(child,left?lo:values[at],left?values[at]:hi);});return visit(0,-Infinity,Infinity);});unique(b,valid);
 }else if(n===6){scene(b,"array",v);const source=Array.from({length:8},(_,i)=>Array.from({length:8},(_,j)=>v[1]===0?(j===1||i===0&&j>=1&&j<=6||i===3&&j>=1&&j<=4):v[1]===1?(j===1||i===7&&j>=1&&j<=6):(j===1||i===0&&j>=1&&j<=5||i===3&&j>=1&&j<=5||j===5&&i<=3)));const rotated=(op:number)=>{let out=source.map(r=>[...r]);if(op===2)return source.map(row=>[...row].reverse());const steps=op===0?2:op===1?3:1;for(let k=0;k<steps;k++)out=out[0].map((_,c)=>out.map(row=>row[c]).reverse());return out;};const expected=rotated(v[0]);unique(b,choices.map((c,index)=>{assert.equal(c,["B(7−i，7−j) ← A(i，j)","B(7−j，i) ← A(i，j)","B(i，7−j) ← A(i，j)","B(j，7−i) ← A(i，j)"][index]);return JSON.stringify(rotated(index))===JSON.stringify(expected);}));
 }else if(n===7){const n0=Number(prompt.match(/場合、(\d{5})は/)![1]);assert.equal(n0,[54321,43125,67214,35824,91425,25743][v[0]]);let j=n0,sum=0;while(j){sum+=j%10;j=Math.floor(j/10);}const answer=sum-13*Math.floor(sum/13);scene(b,"hash",[13]);unique(b,nums.map(x=>x===answer));assert(nums.every(x=>Number.isInteger(x)&&x>=0&&x<13));
 }else if(n===8){const target=Number(prompt.match(/f\((\d)\)の値/)![1]);assert.equal(target,v[0]);let result=1;for(let i=2;i<=target;i++)result+=i;unique(b,nums.map(x=>x===result));
 }else if(n===11){const width=Number(prompt.match(/、(\d+)ビットのデータバス幅/)![1]);let exponent=0;while(2**exponent<width)exponent++;assert.equal(2**exponent,width);assert.equal(exponent,v[0]);unique(b,nums.map(x=>x===exponent+2));
 }else if(n===12){const rows=tables(b.prompt)[0].rows;assert.equal(rows.length,4);const reviewed=[[[15,0,0],[30,0,0],[70,20,60],[80,10,90]],[[10,0,0],[20,0,0],[60,10,50],[100,10,50]],[[30,0,0],[60,0,0],[20,5,80],[40,10,75]],[[40,0,0],[60,0,0],[30,10,80],[20,5,90]]];assert.deepEqual(rows.map(r=>[Number(r[4]),r[1]==="なし"?0:Number(r[2]),r[1]==="なし"?0:Number(r[3])]),reviewed[v[0]]);const times=(extra:boolean)=>rows.map(r=>r[1]==="なし"?Number(r[4]):(Number(r[2])*Number(r[3])+(Number(r[4])+(extra?Number(r[2]):0))*(100-Number(r[3])))/100);const orders=[false,true].map(extra=>times(extra).map((time,i)=>({time,id:"ABCD"[i]})).sort((a,b)=>a.time-b.time).map(x=>x.id).join("，"));assert.equal(orders[0],orders[1]);unique(b,choices.map(c=>c===orders[0]));
 }else if(n===13){const total=Number(prompt.match(/物理マシン(\d+)台/)![1]),use=Number(prompt.match(/使用率が(\d+)％/)![1]);assert.deepEqual([total,use],[v[0],v[1]*10]);const needed=Array.from({length:total-1},(_,i)=>i+1).find(stop=>use*total>90*(total-stop));unique(b,nums.map(x=>x===needed));
 }else if(n===14){const m=prompt.match(/1台のサーバ、(\d)台のクライアント及び(\d)台のプリンタ/)!;assert.deepEqual(m.slice(1).map(Number),v);scene(b,"availability",v);const formulas=choices.map(c=>c.replace(/\^\d/g,"^n"));assert.equal(formulas.length,4);const truth=choices.map((formula,i)=>{assert.equal(formula,[`ab^${v[0]}c^${v[1]}`,`a(1−b^${v[0]})(1−c^${v[1]})`,`a(1−b)^${v[0]}(1−c)^${v[1]}`,`a(1−(1−b)^${v[0]})(1−(1−c)^${v[1]})`][i]);return [[.5,.5,.5],[.8,.9,.6],[1,1,1],[.7,.2,.4]].every(([a,client,printer])=>{let expected=0;for(let mask=0;mask<2**(1+v[0]+v[1]);mask++){let chance=1;const states=Array.from({length:1+v[0]+v[1]},(_,bit)=>Boolean(mask&(1<<bit)));states.forEach((up,bit)=>{const rate=bit===0?a:bit<=v[0]?client:printer;chance*=up?rate:1-rate;});if(states[0]&&states.slice(1,1+v[0]).some(Boolean)&&states.slice(1+v[0]).some(Boolean))expected+=chance;}const actual=[a*client**v[0]*printer**v[1],a*(1-client**v[0])*(1-printer**v[1]),a*(1-client)**v[0]*(1-printer)**v[1],a*(1-(1-client)**v[0])*(1-(1-printer)**v[1])][i];return Math.abs(actual-expected)<1e-10;});});unique(b,truth);
 }else if(n===15){scene(b,"buffer",[0]);assert(prompt.includes(`に${v[0]===1?"T":v[0]+"T"}秒間`));unique(b,choices.map((c,i)=>{assert.equal(c,[`L＜(R−S)×${v[0]===1?"T":v[0]+"T"}`,`L＜(S−R)×${v[0]===1?"T":v[0]+"T"}`,`L≧(R−S)×${v[0]===1?"T":v[0]+"T"}`,`L≧(S−R)×${v[0]===1?"T":v[0]+"T"}`][i]);let accepts=false;for(let S=1;S<=6;S++)for(let R=0;R<S;R++)for(let T=0;T<=3;T++)for(let L=0;L<=100;L++){const need=(S-R)*v[0]*T,threshold=(i===0||i===2?-1:1)*need,condition=i<2?L<threshold:L>=threshold;if(condition){accepts=true;if(L<need)return false;}}return accepts;}));
 }else if(n===17){const requests=prompt.match(/要求は順に([\d，]+)（/)![1].split("，").map(Number),used=[0,0,0],capacity=10000;assert.deepEqual(requests,[[90,30,40,40,70,30],[20,20,20,40,30,20],[20,20,20,40,20,30],[20,20,20,30,40,20]][v[0]].map(x=>x*v[1]));assert.equal(requests.length,6);for(const request of requests){const free=used.map(u=>capacity-u),at=free.indexOf(Math.max(...free));used[at]+=request;}assert.equal(new Set(used).size,3);const order=[0,1,2].sort((a,b)=>used[b]-used[a]).map(i=>"ABC"[i]).join("，");unique(b,choices.map(c=>c===order));
 }else if(n===20){assert.deepEqual(tables(b.prompt)[0].columns,["伝票番号","注文日","商品コード","数量","顧客コード"]);const kinds=[[/連番に抜け/,"シーケンスチェック"],[/重複していない/,"重複チェック"],[/年月日の文字の並び/,"フォーマットチェック"],[/以前の営業日/,"論理チェック"]] as const;const expected=kinds.find(([pattern])=>pattern.test(prompt));assert(expected);assert.equal(kinds.indexOf(expected),v[0]);unique(b,choices.map(c=>c===expected[1]));
 }else if(n===22){scene(b,"multiplicity",v);const ranges=[[1,Infinity,0,Infinity],[1,1,1,1],[0,1,1,Infinity],[1,1,1,Infinity]][v[0]],models:{totalEqual:boolean;multiple:boolean;empty:boolean;orphan:boolean}[]=[];for(let departments=1;departments<=3;departments++)for(let workers=1;workers<=3;workers++)for(let bits=0;bits<2**(departments*workers);bits++){const perWorker=Array(workers).fill(0),perDept=Array(departments).fill(0);for(let d=0;d<departments;d++)for(let w=0;w<workers;w++)if(bits&(1<<(d*workers+w))){perWorker[w]++;perDept[d]++;}if(perWorker.every(x=>x>=ranges[0]&&x<=ranges[1])&&perDept.every(x=>x>=ranges[2]&&x<=ranges[3]))models.push({totalEqual:departments===workers,multiple:perWorker.some(x=>x>1),empty:perDept.some(x=>x===0),orphan:perWorker.some(x=>x===0)});}assert(models.length);unique(b,choices.map(c=>c.includes("総数")?models.every(m=>m.totalEqual):c.includes("複数")?models.some(m=>m.multiple):c.includes("所属する従業員")?c.includes("許されない")?models.every(m=>!m.empty):models.some(m=>m.empty):models.some(m=>m.orphan)));
 }else if(n===24){const [x,y]=tables(b.prompt);assert(x&&y);assert.deepEqual(x.rows.map(r=>r[3]),[20,15,8,10,5].map(n=>String(n+v[1])));const projection=y.columns.length<x.columns.length;assert.equal(projection,v[0]===0);const expected=projection?"射影（projection）":"選択（selection）";if(projection){assert.deepEqual(y.columns,["商品番号","数量"]);const indices=y.columns.map(name=>x.columns.indexOf(name));assert.deepEqual(y.rows,x.rows.map(r=>indices.map(i=>r[i])));}else{assert.deepEqual(y.columns,x.columns);assert.deepEqual(y.rows,x.rows.filter(r=>Number(r[3])>=15+v[1]));}unique(b,choices.map(c=>c===expected));
 }else if(n===26){const m=prompt.match(/([\d.]+)Mビット／秒の伝送路を用いて(\d+)Mバイト/)!;const rate=Number(m[1]),size=Number(m[2]);assert.deepEqual([rate,size],[v[1]*1.5,v[0]*3]);const bits=size*1000000*8;unique(b,nums.map(seconds=>seconds*rate*1000000/2===bits));assert(nums.every(Number.isInteger));
 }else if(n===29){const m=prompt.match(/割り当てた(\d+)、宛先ポート番号は(\d+)/)!;assert.deepEqual(m.slice(1).map(Number),[50001+v[0],[80,8080,8000][v[1]]]);unique(b,b.choices.map(c=>{const [source,dest]=tables(c)[0].rows[0];return source===m[2]&&dest===m[1];}));
 }else if(n===44){scene(b,"network",v);const durations=[v[0],2,1,4,v[1],3,3,2,1,4];const paths:number[]=[];function walk(node:number,total:number){if(node===8)paths.push(total);for(const [i,[a,z]] of decAReviewedNetworkEdges.entries())if(a===node)walk(z,total+durations[i]);}walk(0,0);assert.equal(paths.length,3);unique(b,nums.map(x=>paths.every(days=>x>=days)&&paths.some(days=>x===days)));
 }else if(n===50){const ts=tables(b.prompt);assert.equal(ts.length,4);assert.deepEqual(ts.map(t=>t.rows[0].slice(2).map(Number)),[[15,30,45,30,15],[105,75,45,15,0],[60,75,90,75,60],[105,105,105,105,105]].map((row,i)=>row.map(n=>n*v[1]*(v[0]>0&&i===v[0]?2:1))));assert.deepEqual(ts.map(t=>Number(t.rows[1][1])),[100,200,300,400].map(n=>n*v[1]));const profits=ts.map(t=>t.rows[0].slice(2).reduce((a,x)=>a+Number(x),0)),investments=ts.map(t=>Number(t.rows[1][1]));const winners=investments.map((x,i)=>investments.every((y,j)=>profits[i]*y>=profits[j]*x));assert.equal(winners.filter(Boolean).length,1);unique(b,choices.map(c=>winners["abcd".indexOf(c)]));
 }else if(n===57){const rows=tables(b.prompt)[0].rows;assert.deepEqual(rows.map(r=>r.slice(0,3)),[["A","2","1"],["B","1","2"]]);const [A,B]=rows.map(r=>Number(r[3]));assert.deepEqual([A,B],[100*v[0]+6*v[1],80*v[0]]);let max=-Infinity;for(let x=0;x<=A/2;x++)for(let y=0;y<=B/2;y++)if(2*x+y<=A&&x+2*y<=B)max=Math.max(max,100*x+150*y);unique(b,nums.map(x=>x===max));assert(nums.every(Number.isInteger));assert(Math.min(...nums.filter(x=>x!==max).map(x=>Math.abs(x-max)))>=500);
 }else if(n===58){const m=prompt.match(/に(\d+)万円で購入したPCを3年後に([\d.]+)万円で売却/)!;const cost=Number(m[1]),sale=Number(m[2]);assert.deepEqual([cost,sale],[v[0]*2,v[1]/2]);let book=cost;for(let year=0;year<3;year++)book-=cost*.25;unique(b,nums.map(x=>x===book-sale));assert(choices.every(c=>/^\d+\.\d$/.test(c)));assert(Math.min(...nums.filter(x=>x!==book-sale).map(x=>Math.abs(x-(book-sale))))>=.5);
 }else if(n===59){const m=prompt.match(/売上高が(\d+)百万円のとき、変動費が(\d+)百万円、固定費が(\d+)百万円/)!;const target=Number(prompt.match(/目標利益(\d+)百万円/)![1]);const [sales,variable,fixed]=m.slice(1).map(Number);assert.deepEqual([sales,variable,fixed,target],[100*v[0],60*v[0],30*v[0],6*v[1]]);unique(b,nums.map(x=>x*sales-x*variable-fixed*sales===target*sales));assert(nums.every(Number.isInteger));const actual=nums[b.correctIndex!];assert(Math.min(...nums.filter(x=>x!==actual).map(x=>Math.abs(x-actual)))>=actual*.099999);
 }else if(n===60){scene(b,"dispatch",v);const mapping=[[/派遣先企業と労働者/,"指揮命令関係"],[/派遣元企業と労働者/,"雇用契約関係"],[/派遣元企業と派遣先企業/,"労働者派遣契約関係"]] as const;const fact=mapping.find(([pattern])=>pattern.test(prompt));assert(fact);unique(b,choices.map(c=>c===fact[1]));
 }else decAKnowledgeOracle(n,b,v);
}
